/* non-opaque: one named creator per route, return by value */
static inline struct timespec timespec_from_ms(long ms) {
    return (struct timespec){ .tv_sec = ms / 1000, .tv_nsec = (ms % 1000) * 1000000L };
}
/* opaque handle: representation hidden, creation/destruction paired */
struct ringbuf *ringbuf_create_with_capacity(size_t cap);
void ringbuf_destroy(struct ringbuf *rb);
